class _Cell:
    """Base class for cells in the reactive graph."""

    def __init__(self):
        self._dependents = []

    def _add_dependent(self, dependent):
        self._dependents.append(dependent)

    def _notify(self):
        """Propagate a change to all affected compute cells.

        Collects every compute cell reachable through the dependents graph,
        then recomputes them in topological order so that each cell always
        sees its inputs' final values for the new stable state.
        """
        affected = []
        seen = set()
        stack = [self]
        while stack:
            cell = stack.pop()
            for dependent in cell._dependents:
                if dependent not in seen:
                    seen.add(dependent)
                    affected.append(dependent)
                    stack.append(dependent)
        if not affected:
            return

        # A cell is ready to recompute once every affected input of its own
        # has already been recomputed.
        pending = {
            cell: sum(1 for input in cell._inputs if input in seen)
            for cell in affected
        }
        updated = set()
        ready = [cell for cell in affected if pending[cell] == 0]
        while ready:
            cell = ready.pop()
            if cell in updated:
                continue
            updated.add(cell)
            cell._recompute()
            for dependent in cell._dependents:
                if dependent in seen:
                    pending[dependent] -= 1
                    if pending[dependent] == 0:
                        ready.append(dependent)


class InputCell(_Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        self._notify()


class ComputeCell(_Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = inputs
        self._compute_function = compute_function
        self._callbacks = []
        self._value = self._compute_function([input.value for input in inputs])
        for input in inputs:
            input._add_dependent(self)

    @property
    def value(self):
        return self._value

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

    def _recompute(self):
        old_value = self._value
        self._value = self._compute_function([input.value for input in self._inputs])
        if self._value != old_value:
            for callback in self._callbacks:
                callback(self._value)

